"""Configure only the disposable CI stack generated by `supabase init`."""
from pathlib import Path
import re

config = Path('supabase/config.toml')
text = config.read_text()

def setting(section, key, value):
    global text
    pattern = rf'(?ms)(^\[{re.escape(section)}\]\s*\n(?:(?!^\[).)*?^{re.escape(key)}\s*=\s*)[^\n]+'
    text, count = re.subn(pattern, lambda match: match.group(1) + value, text, count=1)
    if count != 1:
        raise SystemExit(f'Missing generated CLI setting: [{section}] {key}')

setting('auth', 'site_url', '"http://localhost:3001"')
setting('auth.email', 'enable_confirmations', 'false')
setting('studio', 'enabled', 'false')
setting('analytics', 'enabled', 'false')
setting('edge_runtime', 'enabled', 'false')
setting('db.seed', 'enabled', 'false')
config.write_text(text)
